<?php require 'config/conexion.php';require 'config/funciones.php';$total=(int)$pdo->query("SELECT COUNT(*) FROM denuncias")->fetchColumn();$rows=$pdo->query("SELECT estatus,COUNT(*) n FROM denuncias GROUP BY estatus")->fetchAll();?><!doctype html><html lang="es"><head><meta charset="utf-8"><link rel="stylesheet" href="assets/css/estilos.css"><title>Estadísticas</title></head><body><main class="wrap"><h1>Estadísticas generales</h1><section class="cards"><div class="panel"><small>TOTAL DE DENUNCIAS</small><h2><?=$total?></h2></div><?php foreach($rows as $r):?><div class="panel"><small><?=e($r['estatus'])?></small><h2><?=$r['n']?></h2></div><?php endforeach;?></section><p>Datos agregados del prototipo local.</p><a href="index.php">Volver</a></main></body></html>